metadata.er-schema:
{
  "title": "looply · 翻译模块 实体关系图",
  "version": "v1.0 · 2026-05-11",
  "tables": [
    {
      "name": "language",
      "comment": "语言",
      "columns": [
        {
          "name": "language_code",
          "comment": "语言代码（如en/fr/de）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "language_name",
          "comment": "语言名称（英文）",
          "constraint": ""
        },
        {
          "name": "language_name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "rtl",
          "comment": "是否从右到左",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 639-1 作主键，外部引用（归属 Market 模块管理）"
    },
    {
      "name": "translation",
      "comment": "翻译内容",
      "columns": [
        {
          "name": "translation_id",
          "comment": "翻译ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型（product/category/cms/brand/attribute）",
          "constraint": ""
        },
        {
          "name": "resource_id",
          "comment": "资源ID",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": ""
        },
        {
          "name": "language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "translated_value",
          "comment": "翻译内容",
          "constraint": ""
        },
        {
          "name": "translation_source",
          "comment": "翻译来源（manual/ai/vendor）",
          "constraint": ""
        },
        {
          "name": "source_version",
          "comment": "源内容版本号",
          "constraint": ""
        },
        {
          "name": "source_hash",
          "comment": "源内容哈希",
          "constraint": ""
        },
        {
          "name": "status",
