          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型",
          "constraint": ""
        },
        {
          "name": "vendor_id",
          "comment": "指派供应商（可空）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "priority",
          "comment": "优先级（high/medium/low）",
          "constraint": ""
        },
        {
          "name": "deadline",
          "comment": "截止时间",
          "constraint": ""
        },
        {
          "name": "total_items",
          "comment": "总条目数",
          "constraint": ""
        },
        {
          "name": "completed_items",
          "comment": "已完成条目数",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（pending/in_progress/completed/cancelled）",
          "constraint": ""
        }
      ],
      "note": "批量翻译下发单元，支持指派供应商或内部AI处理"
    },
    {
      "name": "translation_job_item",
      "comment": "翻译任务条目",
      "columns": [
        {
          "name": "item_id",
          "comment": "条目ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "job_id",
          "comment": "归属任务",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "translation_id",
          "comment": "关联翻译记录",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_text",
          "comment": "源文本（快照）",
          "constraint": ""
        },
        {
          "name": "translated_text",
          "comment": "译文",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（pending/in_progress/completed/rejected）",
          "constraint": ""
        },
        {
          "name": "assigned_at",
          "comment": "分配时间",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "完成时间",
          "constraint": ""
