          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_text",
          "comment": "源文本",
          "constraint": ""
        },
        {
          "name": "translated_text",
          "comment": "译文",
          "constraint": ""
        },
        {
          "name": "source_hash",
          "comment": "源文本哈希（快速匹配）",
          "constraint": ""
        },
        {
          "name": "match_count",
          "comment": "被复用次数",
          "constraint": ""
        },
        {
          "name": "last_used_at",
          "comment": "最近使用时间",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/deprecated）",
          "constraint": ""
        }
      ],
      "note": "历史翻译复用，source_hash 快速匹配相同/相似源文本"
    },
    {
      "name": "glossary_term",
      "comment": "术语表",
      "columns": [
        {
          "name": "term_id",
          "comment": "术语ID",
          "constraint": "PRIMARY KEY"
        },
        {
