          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_term",
          "comment": "源术语",
          "constraint": ""
        },
        {
          "name": "translated_term",
          "comment": "标准译法",
          "constraint": ""
        },
        {
          "name": "context",
          "comment": "使用场景说明",
          "constraint": ""
        },
        {
          "name": "category",
          "comment": "术语分类（brand/industry/ui/general）",
          "constraint": ""
        },
        {
          "name": "is_case_sensitive",
          "comment": "是否区分大小写",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/deprecated）",
          "constraint": ""
        }
      ],
      "note": "品牌词/行业术语统一翻译，确保全站一致性"
    },
    {
