          "comment": "类型（agency/freelancer/platform）",
          "constraint": ""
        },
        {
          "name": "contact_email",
          "comment": "联系邮箱",
          "constraint": ""
        },
        {
          "name": "api_endpoint",
          "comment": "API对接地址（可空）",
          "constraint": ""
        },
        {
          "name": "pricing_model",
          "comment": "计价模式（per_word/per_hour/fixed）",
          "constraint": ""
        },
        {
          "name": "avg_turnaround_hours",
          "comment": "平均交付时长（小时）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/suspended/terminated）",
          "constraint": ""
        }
      ],
