        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "quality_tier",
          "comment": "质量等级（standard/professional/premium）",
          "constraint": ""
        },
        {
          "name": "price_per_word",
          "comment": "每词单价",
          "constraint": ""
