      "comment": "翻译质量评分",
      "columns": [
        {
          "name": "score_id",
          "comment": "评分ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "translation_id",
          "comment": "关联翻译记录",
          "constraint": "FOREIGN KEY"
        },
        {
