          "constraint": ""
        },
        {
          "name": "terminology_score",
          "comment": "术语一致性评分（1-5）",
          "constraint": ""
        },
        {
          "name": "overall_score",
          "comment": "综合评分（1-5）",
          "constraint": ""
        },
        {
