  "relations": [
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "translation_job",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#E8833A",
      "penwidth": 1.2
    },
    {
      "from": "translation_job",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#E8833A",
      "penwidth": 1.2
    },
    {
      "from": "translation_job",
      "to": "translation_vendor",
      "type": "N:1",
      "label": "指派供应商",
      "color": "#1565C0",
      "penwidth": 1.2,
      "style": "dashed"
    },
    {
      "from": "translation_job_item",
      "to": "translation_job",
      "type": "N:1",
      "label": "归属任务",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "translation_job_item",
      "to": "translation",
      "type": "N:1",
      "label": "关联翻译",
      "color": "#7B1FA2",
      "penwidth": 1.2
    },
    {
      "from": "translation_memory",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#2E7D32"
    },
    {
      "from": "translation_memory",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#2E7D32"
    },
    {
      "from": "glossary_term",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#2E7D32"
    },
    {
      "from": "glossary_term",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#2E7D32"
    },
    {
      "from": "vendor_language_capability",
      "to": "translation_vendor",
      "type": "N:1",
      "label": "归属供应商",
      "color": "#1565C0",
      "penwidth": 1.4
    },
    {
      "from": "vendor_language_capability",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#1565C0"
    },
    {
      "from": "vendor_language_capability",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#1565C0"
    },
    {
      "from": "translation_quality_score",
      "to": "translation",
      "type": "N:1",
      "label": "关联翻译",
      "color": "#E65100",
      "penwidth": 1.4
    }
  ],
  "design_rules": {
    "eav_pattern": "translation 表采用 EAV 模式（resource_type + resource_id + field_name），一张表存储所有业务实体的翻译内容，按需扩展 resource_type 即可",
    "translation_strategy": "混合策略：核心内容（商品/类目）集中翻译+人工审核，长尾内容（UGC）AI翻译+抽检。source_hash 检测源内容变化，status=outdated 触发重译",
    "language_fk": "翻译关联 language_code（ISO 639-1），不建 locale 实体。BCP 47 locale 在运行时由 language_code + country_code 拼接",
    "translation_memory": "翻译记忆库通过 source_hash 快速匹配历史翻译，match_count 统计复用频率，辅助翻译效率提升",
    "glossary_enforcement": "术语表为强约束：翻译时必须匹配术语表中的标准译法，确保品牌词和行业术语全站一致",
    "vendor_assignment": "翻译任务可指派供应商（vendor_id），也可留空由内部AI处理。vendor_language_capability 记录供应商的语言对能力和报价，支持自动匹配最优供应商",
    "quality_scoring": "质量评分支持人工（human）和自动（auto）两种来源，从准确性、流畅度、术语一致性三个维度打分，overall_score 为综合评分",
    "job_lifecycle": "翻译任务生命周期：pending → in_progress → completed/cancelled。任务条目完成后自动回写 translation 表的 translated_value 和 status",
    "audit_fields": "所有实体统一通过数据库层自动维护审计字段（created_by/created_at/updated_by/updated_at），不在 ER 图中逐表重复列出"
  }
}
